// Workflow C / C.2 - the patient-facing webhook is authenticated before anything
// else runs. Fail closed: an unset DJANGO_WEBHOOK_SECRET rejects every request,
// exactly like 05's dispatcher. No `|| 'clinic_dev_...'` fallback is allowed.
const src = $input.first().json || {};
const headers = src.headers || {};

const env = (name) => { try { const v = $env[name]; return v == null ? '' : String(v); } catch (e) { return ''; } };

const expected = env('DJANGO_WEBHOOK_SECRET');
const provided = String(headers['x-webhook-secret'] || '').trim();
const authorized = Boolean(expected) && provided === expected;

return [{ json: {
  ...src,
  reply_auth: {
    authorized: authorized,
    reason: authorized ? null : (expected ? 'bad_secret' : 'secret_not_configured'),
  },
} }];

// Turn either provider payload into the one neutral shape Django accepts:
// {phone, text, channel, provider_message_id}. Nothing is interpreted here -
// "2" stays "2"; Django decides what it means.
const src = $input.first().json || {};
const body = (src.body && typeof src.body === 'object') ? src.body : {};

const str = (v) => (v === undefined || v === null) ? '' : String(v);
const trimmed = (v, max) => str(v).trim().slice(0, max);

// ---- Meta WhatsApp Cloud API envelope -------------------------------------
const metaValue = body.object === 'whatsapp_business_account'
  ? ((((body.entry || [])[0] || {}).changes || [])[0] || {}).value || {}
  : null;

if (metaValue) {
  const messages = Array.isArray(metaValue.messages) ? metaValue.messages : [];
  if (!messages.length) {
    // A status callback (sent/delivered/read) is not a reply. 07 owns those;
    // this workflow answers 200 and does nothing, so Meta never retries here.
    return [{ json: { action: 'ignore', reason: 'not_a_message' } }];
  }
  const msg = messages[0] || {};
  let text = '';
  if (msg.type === 'text') text = (msg.text || {}).body || '';
  else if (msg.type === 'button') text = (msg.button || {}).payload || (msg.button || {}).text || '';
  else if (msg.type === 'interactive') {
    const pick = (msg.interactive || {}).button_reply || (msg.interactive || {}).list_reply || {};
    text = pick.id || pick.title || '';
  } else if (msg.image && msg.image.caption) text = msg.image.caption;
  else if (msg.document && msg.document.caption) text = msg.document.caption;
  else if (msg.video && msg.video.caption) text = msg.video.caption;

  const phone = trimmed(msg.from, 32);
  if (!phone) return [{ json: { action: 'bad_request', reason: 'missing_phone' } }];
  return [{ json: {
    action: 'reply',
    phone: phone,
    text: trimmed(text, 500),
    channel: 'whatsapp',
    provider_message_id: trimmed(msg.id, 255),
  } }];
}

// ---- VoiceBip SMS (flat payload; field names still being confirmed) --------
const phone = trimmed(body.phone || body.from || body.sender || body.msisdn || body.to, 32);
if (!phone) return [{ json: { action: 'bad_request', reason: 'missing_phone' } }];

const rawText = (body.text !== undefined && body.text !== null) ? body.text
  : ((body.message !== undefined && body.message !== null) ? body.message : body.body);
const text = (typeof rawText === 'string' || typeof rawText === 'number') ? trimmed(rawText, 500) : '';

const claimed = str(body.channel).toLowerCase();
const channel = (claimed === 'sms' || claimed === 'whatsapp') ? claimed : 'sms';

return [{ json: {
  action: 'reply',
  phone: phone,
  text: text,
  channel: channel,
  provider_message_id: trimmed(body.id || body.message_id || body.sms_id || body.external_ref, 255),
} }];

// Build the outbound reply in the channel the patient used. Copy comes from
// Django (`reply_text`) and is sent verbatim - this node only wraps it in the
// provider's shape. Mock mode points at 06's simulator, like 05's adapter.
const answer = $input.first().json || {};
const inbound = $('Normalize Patient Reply').first().json || {};

const env = (name, fallback = '') => {
  try { const v = $env[name]; return (v === undefined || v === null) ? fallback : String(v); }
  catch (e) { return fallback; }
};
const truthy = (v) => ['1', 'true', 'yes', 'on'].includes(String(v).trim().toLowerCase());

const providerMock = env('PROVIDER_MOCK') === '' ? true : truthy(env('PROVIDER_MOCK'));

const cfg = {
  voicebipApiUrl: env('VOICEBIP_API_URL'),
  voicebipApiKey: env('VOICEBIP_API_KEY'),
  smsSenderId: env('VOICEBIP_SMS_SENDER_ID', 'Cedarcare'),
  whatsappApiUrl: env('WHATSAPP_API_URL', 'https://graph.facebook.com/v19.0/'),
  whatsappPhoneId: env('WHATSAPP_PHONE_NUMBER_ID'),
  whatsappToken: env('WHATSAPP_ACCESS_TOKEN'),
  simulatorUrl: env('PROVIDER_SIMULATOR_URL', 'http://127.0.0.1:5678/webhook/provider-sim'),
};

const channel = String(answer.channel || inbound.channel || '').toLowerCase();
const replyText = String(answer.reply_text || '');
const requestCode = answer.request_id || '';
const phone = inbound.phone || '';
const waTo = phone.replace(new RegExp('[^0-9]', 'g'), '');

const skip = (reason) => ({
  reply: answer,
  phone: phone,
  provider_message_id: inbound.provider_message_id || '',
  provider_request: { route: 'skip', skip_reason: reason },
});

// An empty reply_text is Django's duplicate signal: nothing to deliver.
if (!replyText.trim()) return [{ json: skip('empty_reply') }];
// This endpoint owns SMS and WhatsApp. Telegram is Django's own conversation.
if (channel !== 'sms' && channel !== 'whatsapp') return [{ json: skip('channel_not_supported') }];
// Live mode without credentials must not guess: refuse and be visible.
if (channel === 'whatsapp' && !providerMock && !(cfg.whatsappPhoneId && cfg.whatsappToken)) return [{ json: skip('provider_not_configured') }];
if (channel === 'sms' && !providerMock && !(cfg.voicebipApiUrl && cfg.voicebipApiKey)) return [{ json: skip('provider_not_configured') }];

const body = channel === 'whatsapp'
  ? {
      messaging_product: 'whatsapp',
      to: waTo,
      type: 'text',
      // Free-form text is allowed here: the patient just messaged us, so the
      // 24-hour customer-service window is open.
      text: { body: replyText },
      biz_opaque_callback_data: requestCode,
    }
  : {
      to: phone,
      message: replyText,
      sender_id: cfg.smsSenderId,
      metadata: { request_code: requestCode, channel: 'sms' },
    };

const url = channel === 'whatsapp'
  ? (providerMock ? cfg.simulatorUrl + '/whatsapp' : cfg.whatsappApiUrl + cfg.whatsappPhoneId + '/messages')
  : (providerMock ? cfg.simulatorUrl + '/sms' : cfg.voicebipApiUrl + '/sms');

const headers = channel === 'whatsapp'
  ? { Authorization: 'Bearer ' + (providerMock ? 'mock' : cfg.whatsappToken) }
  : { Authorization: 'Bearer ' + (providerMock ? 'mock' : cfg.voicebipApiKey) };

return [{ json: {
  reply: answer,
  phone: phone,
  provider_message_id: inbound.provider_message_id || '',
  provider_request: { route: channel, url: url, headers: headers, body: body },
} }];

// Workflow C / C.2 - record the outbound reply as one `direction=outbound` row.
// Django already wrote the INBOUND row (C.1) and owns the copy and the state;
// this row is the other half of the conversation. Best-effort by design: a
// Django outage while logging must never take the patient flow down.
//
// Do NOT post the inbound message here: that would duplicate the patient's own
// row and contradict the fill-only rule for callbacks.
const incoming = $input.first().json || {};
const prepared = $('Prepare Reply Delivery').first().json || {};
const reply = prepared.reply || {};
const req = prepared.provider_request || {};

const isError = Boolean(incoming.error);
const resp = isError ? {} : incoming;
const skipped = req.route === 'skip';

// >>> provider-error-classification (canonical copy — byte-identical in all three
// Log * Interaction nodes; test_lognodes.js asserts that) >>>
// n8n hands a failed HTTP call to this node as { message, name, stack } — plus a
// `code` for transport errors. There is NO error.status: the status only exists as
// the message prefix, and the response body is embedded as a JSON *string literal*:
//   404 - "{\"code\":404,\"message\":\"...\"}"
// So the status must be read from the prefix and the body needs a real two-step parse.
const STATUS_LABEL = {
  400: 'Provider rejected the request',
  401: 'Provider authentication failed',
  403: 'Provider refused access',
  404: 'Provider endpoint not found',
  409: 'Provider reported a conflict',
  422: 'Provider rejected the request',
  429: 'Provider rate limit reached',
};
const TRANSPORT_LABEL = {
  ECONNREFUSED: 'Provider endpoint refused the connection',
  ENOTFOUND: 'Provider host could not be resolved',
  ETIMEDOUT: 'Provider did not respond in time',
  ECONNABORTED: 'Provider did not respond in time',
  ECONNRESET: 'Provider closed the connection',
};

// Display-only clean-up: one line, no escape residue, no wrapping quotes.
const tidy = (value) => {
  if (typeof value === 'number') return String(value);
  if (typeof value !== 'string') return '';
  return value
    .replace(/\\[nrt]/g, ' ')
    .replace(/\\"/g, '"')
    .replace(/^["']|["']$/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

// Decode the embedded body: JSON string literal -> JSON payload. A hand-rolled
// .replace(/\\"/g, '"') is NOT equivalent: it corrupts nested escaped quotes and
// the parse then throws, which is how the raw wrapper used to reach reception.
const asObject = (body) => {
  let value = String(body == null ? '' : body).trim();
  for (let i = 0; i < 3; i += 1) {
    if (value[0] === '{') {
      try { return JSON.parse(value); } catch (e) { return null; }
    }
    if (value[0] !== '"') return null;
    const end = value.lastIndexOf('"');
    if (end <= 0) return null;
    try { value = JSON.parse(value.slice(0, end + 1)); } catch (e) { return null; }
  }
  return null;
};

const firstText = (list) => {
  if (!Array.isArray(list)) return '';
  for (const item of list) {
    const text = tidy(typeof item === 'string' ? item : (item && (item.message || item.detail || item.msg)));
    if (text) return text;
  }
  return '';
};

// The provider's own sentence, in the order providers actually use it.
const providerSentence = (body) => {
  const parsed = asObject(body);
  if (!parsed) return tidy(body);
  const err = parsed.error;
  const candidates = [
    parsed.detail, parsed.message, parsed.error_description, parsed.description, parsed.hint,
    typeof err === 'string' ? err : '',
    err && err.message, err && err.title,
    err && err.error_data && err.error_data.details,
    firstText(parsed.errors),
  ];
  for (const candidate of candidates) {
    const text = tidy(candidate);
    if (text) return text;
  }
  return tidy(body);
};

// -> { status: number|null, detail: string (<=300) } — one sentence reception can act on.
const classifyProviderError = (err) => {
  // Parse from the RAW message: tidy() unescapes quotes and must never run first,
  // or the JSON string literal stops being a valid literal.
  const message = (err && typeof err.message === 'string') ? err.message : '';
  const explicit = Number(err && (err.status || err.httpCode || err.statusCode));
  const prefixed = message.match(/^\s*(\d{3})\s*-\s*([\s\S]*)$/);
  const status = (Number.isFinite(explicit) && explicit >= 400) ? explicit
    : (prefixed ? Number(prefixed[1]) : null);
  if (status) {
    const label = STATUS_LABEL[status] || (status >= 500 ? 'Provider server error' : 'Provider returned an error');
    const sentence = providerSentence(prefixed ? prefixed[2] : '');
    return { status, detail: (label + (sentence ? ': ' + sentence : '')).slice(0, 300) };
  }
  const code = tidy(err && err.code).toUpperCase();
  if (TRANSPORT_LABEL[code]) return { status: null, detail: TRANSPORT_LABEL[code].slice(0, 300) };
  return { status: null, detail: (tidy(message) || tidy(err) || 'Provider call failed').slice(0, 300) };
};
// <<< provider-error-classification
const channel = String(reply.channel || 'sms').toLowerCase();
const provider = channel === 'whatsapp' ? 'meta_whatsapp' : 'voicebip';

const providerStatus = String(resp.status || '').toLowerCase();
const failed = isError || skipped || providerStatus === 'failed' || resp.ok === false;

// One actionable sentence for reception. A held-back reply is recorded too:
// the patient is waiting and silence would be invisible.
const SKIP_TEXT = {
  provider_not_configured: 'Provider is not configured yet, so the reply was not sent.',
  channel_not_supported: 'This channel is not handled by the patient-reply workflow, so nothing was sent.',
  empty_reply: 'Django returned an empty reply (a duplicate message), so nothing was sent.',
};

const classified = isError ? classifyProviderError(incoming.error) : null;
const errorDetail = isError
  ? classified.detail
  : (skipped
    ? (SKIP_TEXT[req.skip_reason] || 'The reply was not delivered.')
    : (failed ? String(resp.error_message || resp.error || resp.detail || 'Provider reported a failure').slice(0, 300) : ''));

// Provider message ids, in the order providers actually use them.
const messageId = String(
  (((resp.messages || [])[0] || {}).id) || resp.external_ref || resp.message_id || resp.id || resp.call_id || ''
);

const payload = {
  provider: provider,
  channel: channel,
  direction: 'outbound',
  status: failed ? 'failed' : 'sent',
  patient_phone: prepared.phone || '',
  request_code: reply.request_id || '',
  appointment_code: reply.appointment_code || '',
  external_ref: failed ? '' : messageId,
  summary: failed
    ? 'Reply could not be delivered to the patient.'
    : ('Reply delivered to patient via ' + (channel === 'whatsapp' ? 'WhatsApp' : 'SMS') + '.'),
  error_detail: errorDetail,
};

let logged = { ok: false };
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: $env.DJANGO_API_BASE_URL + '/interactions/',
    headers: { 'Content-Type': 'application/json', 'X-Webhook-Secret': $env.DJANGO_WEBHOOK_SECRET || '' },
    body: payload,
    json: true,
  });
  logged = { ok: true, id: res.id, status: res.status };
} catch (e) {
  logged = { ok: false, error: (e.message || String(e)).slice(0, 300) };
}

return [{ json: { ...prepared, provider_response: resp, reply_result: { ...logged, payload } } }];
